import java.io.*;
import java.util.*;

public class CF1187G extends PrintWriter {
    public CF1187G() { super(System.out); }

    static class InputReader {
        private final InputStream stream;
        private final byte[] buf = new byte[1 << 15];
        private int cur, len;

        InputReader(InputStream s) { stream = s; }

        private int read() throws IOException {
            if (cur >= len) {
                cur = 0;
                len = stream.read(buf);
                if (len <= 0) return -1;
            }
            return buf[cur++];
        }

        int nextInt() throws IOException {
            int c;
            while ((c = read()) <= 32) if (c == -1) return -1;
            int x = 0;
            while (c > 32) {
                x = x * 10 + c - '0';
                c = read();
            }
            return x;
        }
    }

    InputReader in;

    public static void main(String[] args) {
        new CF1187G().execute();
    }

    static final int INF = 0x3f3f3f3f;
    List<Integer>[] adj;
    int V, E;
    int[] dist, prevDist, prevEdge;
    int[] from, to, xorVal, w;
    int[] cap;

    void prepare(int n, int m) {
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        dist = new int[n];
        prevDist = new int[n];
        prevEdge = new int[n];
        from = new int[m];
        to = new int[m];
        xorVal = new int[m];
        w = new int[m];
        cap = new int[m * 2];
        E = 0;
    }

    void addEdge(int u, int v, int c, int cost) {
        int idx = E++;
        from[idx] = u;
        to[idx] = v;
        xorVal[idx] = u ^ v;
        w[idx] = cost;
        cap[idx * 2] = c;
        adj[u].add(idx * 2);
        adj[v].add(idx * 2 + 1);
    }

    int[] q;
    int qf, qb, ql;
    boolean[] inq;

    void push(int x) {
        if (inq[x]) return;
        if (qf + ql == q.length) {
            if (ql * 2 <= q.length) {
                System.arraycopy(q, qf, q, 0, ql);
                qf = 0;
            } else {
                int[] nq = new int[q.length * 2];
                System.arraycopy(q, qf, nq, 0, ql);
                q = nq;
                qf = 0;
            }
        }
        q[qf + ql++] = x;
        inq[x] = true;
    }

    int pop() {
        int x = q[qf++];
        ql--;
        inq[x] = false;
        return x;
    }

    boolean spfa(int s, int t) {
        Arrays.fill(dist, INF);
        dist[s] = 0;
        qf = ql = 0;
        push(s);

        while (ql > 0) {
            int u = pop();
            int nd = prevDist[u] + 1;

            for (int e : adj[u]) {
                if (cap[e] > 0) {
                    int idx = e >> 1;
                    int c = (e & 1) == 0 ? w[idx] : -w[idx];
                    int ndist = dist[u] + c;
                    int v = u ^ xorVal[idx];

                    if (dist[v] > ndist || (dist[v] == ndist && prevDist[v] > nd)) {
                        dist[v] = ndist;
                        prevDist[v] = nd;
                        prevEdge[v] = e;
                        push(v);
                    }
                }
            }
        }
        return dist[t] != INF;
    }

    void augment(int s, int t) {
        int minCap = INF;
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            minCap = Math.min(minCap, cap[prevEdge[v]]);
        }
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            cap[e] -= minCap;
            cap[e ^ 1] += minCap;
        }
    }

    void augmentUnit(int s, int t) {
        for (int v = t; v != s; v ^= xorVal[prevEdge[v] >> 1]) {
            int e = prevEdge[v];
            cap[e]--;
            cap[e ^ 1]++;
        }
    }

    int minCost(int s, int t) {
        while (spfa(s, t)) {
            augmentUnit(s, t);
        }
        int total = 0;
        for (int i = 0; i < E; i++) {
            total += w[i] * cap[i * 2 + 1];
        }
        return total;
    }

    void execute() {
        try {
            in = new InputReader(System.in);
            int n = in.nextInt();
            int m = in.nextInt();
            int k = in.nextInt();
            int c = in.nextInt();
            int d = in.nextInt();

            int[] special = new int[k];
            for (int i = 0; i < k; i++) special[i] = in.nextInt() - 1;

            List<Integer>[] g = new ArrayList[n];
            for (int i = 0; i < n; i++) g[i] = new ArrayList<>();

            for (int i = 0; i < m; i++) {
                int u = in.nextInt() - 1;
                int v = in.nextInt() - 1;
                g[u].add(v);
                g[v].add(u);
            }

            int T = k + 1;
            int totalNodes = n * T + 1;
            int totalEdges = k + (m * 2 * k + n) * (T - 1);
            prepare(totalNodes, totalEdges);

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    for (int neighbor : g[i]) {
                        int v = neighbor * T + t + 1;
                        for (int x = 1; x <= k; x++) {
                            addEdge(u, v, 1, c + (x * 2 - 1) * d);
                        }
                    }
                }
            }

            for (int i = 0; i < n; i++) {
                for (int t = 0; t < T - 1; t++) {
                    int u = i * T + t;
                    int v = u + 1;
                    addEdge(u, v, k, i == 0 ? 0 : c);
                }
            }

            for (int i = 0; i < k; i++) {
                addEdge(totalNodes - 1, special[i] * T, 1, 0);
            }

            println(minCost(totalNodes - 1, 0 * T + T - 1));
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }
}
